using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

public class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [Fact]
    public async Task AppHostStartsSuccessfully()
    {
        Assert.NotNull(_app);
        // Verify the app host process started and is running.
        await _app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppHostDashboardResponds()
    {
        Assert.NotNull(_app);

        using var client = _app.CreateHttpClient("aspire-dashboard");
        var response = await client.GetAsync("/");
        response.EnsureSuccessStatusCode();
    }
}

